@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500&family=Playfair+Display:ital,wght@0,400;0,500;0,600;1,400;1,500&display=swap');

:root {
  --bg-surface: oklch(96% 0.01 80);      /* Warm off-white */
  --text-primary: oklch(20% 0.02 80);    /* Near black */
  --text-secondary: oklch(45% 0.02 80);  /* Muted gray */
  --text-light: oklch(98% 0.01 80);      /* Off-white */

  --accent-terracotta: oklch(65% 0.15 45);
  --accent-sage: oklch(75% 0.08 140);
  --accent-sand: oklch(85% 0.06 80);

  --font-serif: 'Playfair Display', serif;
  --font-sans: 'Inter', system-ui, sans-serif;

  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 2rem;
  --space-lg: 4rem;
  --space-xl: 8rem;
  --space-xxl: 12rem;

  --header-height: 100px;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-surface);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 500;
  line-height: 1.1;
  color: var(--text-primary);
}

a {
  color: inherit;
  text-decoration: none;
  transition: opacity 0.3s ease;
}

a:hover {
  opacity: 0.6;
}

/* Layout Utilities */
.container {
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 var(--space-md);
}

.reading-container {
  max-width: 680px;
  margin: 0 auto;
  padding: 0 var(--space-md);
}

/* Header */
.site-header {
  height: var(--header-height);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 var(--space-lg);
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 100;
  background-color: rgba(245, 242, 237, 0.8);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.desktop-nav {
  display: flex;
  gap: var(--space-lg);
}

.desktop-nav a {
  font-size: 0.85rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* Mobile Menu Toggle */
.mobile-menu-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  z-index: 101;
  width: 32px;
  height: 20px;
  position: relative;
}

.hamburger-line {
  display: block;
  width: 100%;
  height: 1.5px;
  background-color: var(--text-primary);
  position: absolute;
  transition: all 0.3s ease;
}

.hamburger-line:first-child { top: 0; }
.hamburger-line:last-child { bottom: 0; }

.mobile-menu-toggle.is-active .hamburger-line:first-child {
  transform: translateY(9.25px) rotate(45deg);
}
.mobile-menu-toggle.is-active .hamburger-line:last-child {
  transform: translateY(-9.25px) rotate(-45deg);
}

/* Mobile Navigation Overlay */
.mobile-menu-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: var(--bg-surface);
  z-index: 99;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.mobile-menu-overlay.is-active {
  opacity: 1;
  pointer-events: auto;
}

.mobile-nav {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-md);
}

.mobile-nav a {
  font-family: var(--font-serif);
  font-size: 3.5rem;
  font-style: italic;
  letter-spacing: -0.02em;
}

@media (max-width: 768px) {
  .site-header { padding: 0 var(--space-md); }
  .desktop-nav { display: none; }
  .mobile-menu-toggle { display: block; }
}

/* Main Spacing */
main {
  min-height: 100vh;
}

/* Home Page: Hero */
.hero {
  padding: calc(var(--header-height) + var(--space-xl)) var(--space-lg) var(--space-xl);
  max-width: 1200px;
  margin: 0 auto;
}

.hero h1 {
  font-size: clamp(3.5rem, 7vw, 7.5rem);
  letter-spacing: -0.03em;
  max-width: 18ch;
  line-height: 1.05;
}

/* Home Page: Media Showcase */
.media-showcase {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: var(--space-md);
  padding: 0 var(--space-lg) var(--space-xl);
  max-width: 1600px;
  margin: 0 auto;
}

.media-block {
  aspect-ratio: 4/5;
  border-radius: 2px;
}

.media-block.terracotta { background-color: var(--accent-terracotta); }
.media-block.sage { background-color: var(--accent-sage); }
.media-block.sand { background-color: var(--accent-sand); }

@media (max-width: 768px) {
  .media-showcase { grid-template-columns: 1fr; gap: var(--space-sm); }
}

/* Home Page: Client Marquee */
.client-marquee-section {
  padding: var(--space-xl) 0;
  background-color: var(--text-primary);
  color: var(--text-light);
  overflow: hidden;
}

.marquee-row {
  display: flex;
  white-space: nowrap;
  padding: var(--space-sm) 0;
  font-family: var(--font-sans);
  font-size: clamp(1rem, 2vw, 1.5rem);
  font-weight: 300;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.marquee-content {
  display: flex;
  gap: 3rem;
  padding-right: 3rem;
  /* Add duplicate content in HTML for seamless scrolling */
}

.marquee-item {
  display: flex;
  align-items: center;
  gap: 3rem;
}

.marquee-row.left .marquee-content {
  animation: marquee-left 40s linear infinite;
}

.marquee-row.right .marquee-content {
  animation: marquee-right 40s linear infinite;
}

@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-100%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(0); }
}

/* Home Page: About Section */
.about-section {
  padding: var(--space-xxl) var(--space-lg);
  max-width: 1000px;
  margin: 0 auto;
  text-align: center;
}

.about-section h2 {
  font-family: var(--font-sans);
  font-size: 0.85rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: var(--space-xl);
  color: var(--text-secondary);
}

.about-section p {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2.5rem);
  line-height: 1.4;
  margin-bottom: var(--space-md);
  color: var(--text-primary);
}

/* Founder Letter (neweno.html) */
.founder-letter {
  padding-top: calc(var(--header-height) + var(--space-xl));
  padding-bottom: var(--space-xxl);
}

.founder-letter h1 {
  font-size: clamp(3rem, 6vw, 5rem);
  margin-bottom: var(--space-lg);
  font-style: italic;
  font-weight: 400;
}

.founder-letter p {
  font-size: 1.25rem;
  margin-bottom: var(--space-md);
  color: var(--text-primary);
  line-height: 1.7;
}

/* Services Page */
.services-hero {
  padding: calc(var(--header-height) + var(--space-xl)) 0 var(--space-xl);
}

.services-hero h1 {
  font-size: clamp(3rem, 6vw, 5.5rem);
  margin-bottom: var(--space-md);
  max-width: 800px;
}

.services-hero .philosophy {
  font-family: var(--font-sans);
  font-size: 1.5rem;
  line-height: 1.5;
  max-width: 700px;
  color: var(--text-secondary);
  font-weight: 300;
}

.services-hero .philosophy p {
  margin-bottom: var(--space-md);
}

.divider {
  height: 1px;
  background-color: var(--text-primary);
  opacity: 0.1;
  margin: 0 var(--space-lg);
}

.services-list-container {
  padding: var(--space-xl) var(--space-lg);
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: var(--space-xl);
  max-width: 1440px;
  margin: 0 auto;
}

@media (max-width: 900px) {
  .services-list-container { grid-template-columns: 1fr; }
}

.services-heading {
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-family: var(--font-serif);
  font-style: italic;
  font-weight: 400;
  max-width: 300px;
}

.services-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-xl);
}

.service-item h3 {
  font-size: 2.5rem;
  margin-bottom: var(--space-sm);
  font-family: var(--font-sans);
  letter-spacing: -0.02em;
  font-weight: 400;
}

.service-item p {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 600px;
  line-height: 1.6;
}

/* Clients Page */
.clients-header {
  padding: calc(var(--header-height) + var(--space-xl)) var(--space-lg) var(--space-xl);
  max-width: 1440px;
  margin: 0 auto;
}

.clients-header h1 {
  font-size: clamp(3.5rem, 6vw, 5.5rem);
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl) var(--space-lg);
  padding: 0 var(--space-lg) var(--space-xxl);
  max-width: 1440px;
  margin: 0 auto;
}

@media (max-width: 1024px) {
  .clients-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 600px) {
  .clients-grid { grid-template-columns: 1fr; }
}

.client-card h3 {
  font-family: var(--font-sans);
  font-size: 1.5rem;
  font-weight: 500;
  margin-bottom: var(--space-xs);
  letter-spacing: -0.02em;
}

.client-card p {
  font-size: 1.05rem;
  color: var(--text-secondary);
  line-height: 1.5;
  font-weight: 300;
}

/* Contact Page */
.contact-section {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: calc(var(--header-height) + var(--space-md)) var(--space-lg);
  text-align: center;
}

.contact-section h1 {
  font-size: clamp(4rem, 18vw, 18rem);
  line-height: 0.9;
  margin-bottom: var(--space-xl);
  letter-spacing: -0.04em;
  font-weight: 400;
}

.contact-links {
  display: flex;
  gap: var(--space-xl);
  font-family: var(--font-sans);
  font-size: 1.25rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

@media (max-width: 768px) {
  .contact-links {
    flex-direction: column;
    gap: var(--space-md);
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const mobileMenuToggle = document.querySelector('.mobile-menu-toggle');
  const mobileMenuOverlay = document.querySelector('.mobile-menu-overlay');

  if (mobileMenuToggle && mobileMenuOverlay) {
    mobileMenuToggle.addEventListener('click', () => {
      const isActive = mobileMenuToggle.classList.contains('is-active');

      if (isActive) {
        mobileMenuToggle.classList.remove('is-active');
        mobileMenuOverlay.classList.remove('is-active');
        document.body.style.overflow = '';
      } else {
        mobileMenuToggle.classList.add('is-active');
        mobileMenuOverlay.classList.add('is-active');
        document.body.style.overflow = 'hidden';
      }
    });
  }
});

